import"./chunk-VC46IEJQ.js";var e=(a,s)=>({en:a,zh:s}),n={group:"iron-westerlands",places:[{id:"pyke",houses:["greyjoy","botley","wynch"],refs:["acok","affc","twoiaf"],confidence:"high",summary:e("The Greyjoy seat, built on a broken headland of Pyke whose towers stand on sea-stacks joined by rope bridges. From the Seastone Chair in its great keep the Lord Reaper rules all the Iron Islands.","\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5EFA\u5728\u6D3E\u514B\u5C9B\u4E00\u5904\u65AD\u88C2\u7684\u5CAC\u89D2\u4E0A\uFF0C\u5854\u697C\u5206\u7ACB\u4E8E\u6D77\u4E2D\u77F3\u67F1\uFF0C\u4EE5\u7EF3\u6865\u76F8\u8FDE\u3002\u6536\u5272\u8005\u5927\u4EBA\u5750\u5728\u4E3B\u5821\u4E2D\u7684\u6D77\u77F3\u4E4B\u4F4D\u4E0A\uFF0C\u7EDF\u6CBB\u6574\u4E2A\u94C1\u7FA4\u5C9B\u3002")},{id:"casterly-rock",houses:["lannister"],refs:["agot","twoiaf"],confidence:"high",summary:e("The Lannister seat, a mountain of stone above the Sunset Sea hollowed into halls, stables and harbours, with gold mines running deep beneath. It has never fallen to assault. Its gold has made House Lannister the richest in the realm.","\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF1A\u65E5\u843D\u4E4B\u6D77\u7554\u4E00\u5EA7\u5DE8\u5CA9\uFF0C\u5185\u90E8\u51FF\u51FA\u5385\u5802\u3001\u9A6C\u53A9\u4E0E\u6E2F\u53E3\uFF0C\u5730\u5E95\u6DF1\u5904\u77FF\u8109\u7EB5\u6A2A\u3002\u6B64\u57CE\u4ECE\u672A\u88AB\u653B\u7834\u3002\u6B63\u662F\u8FD9\u91CC\u7684\u9EC4\u91D1\u4F7F\u5170\u5C3C\u65AF\u7279\u6210\u4E3A\u738B\u56FD\u9996\u5BCC\u3002")},{id:"lannisport",houses:["lannister"],refs:["agot","twoiaf"],confidence:"high",summary:e("The great harbour city beneath Casterly Rock, home to a large cadet branch of Lannisters. It is the chief port of the west and was burned by ironborn raiders during Balon Greyjoy's first rebellion.","\u51EF\u5CA9\u57CE\u811A\u4E0B\u7684\u5927\u6E2F\u57CE\uFF0C\u6709\u4E00\u652F\u4EBA\u4E01\u5174\u65FA\u7684\u5170\u5C3C\u65AF\u7279\u65C1\u652F\u5C45\u4F4F\u4E8E\u6B64\u3002\u5B83\u662F\u897F\u5883\u9996\u8981\u6E2F\u53E3\uFF0C\u5DF4\u9686\xB7\u845B\u96F7\u4E54\u4F0A\u9996\u6B21\u53DB\u4E71\u65F6\u66FE\u906D\u94C1\u6C11\u711A\u63A0\u3002")},{id:"ironmans-bay",kind:"bay",region:"iron-islands",at:[262,750],rank:3,names:e("Ironman's Bay","\u94C1\u6C11\u6E7E"),alt:["Ironmans Bay"],summary:e("The broad bay between the Iron Islands and the mainland, bounded by Cape Kraken, the riverlands shore at Seagard and the northern westerlands. For centuries it has been the ironborn's raiding ground.","\u94C1\u7FA4\u5C9B\u4E0E\u5927\u9646\u4E4B\u95F4\u7684\u5BBD\u9614\u6D77\u6E7E\uFF0C\u5317\u8D77\u6D77\u602A\u89D2\uFF0C\u4E1C\u4E34\u6D77\u7586\u57CE\u4E00\u5E26\u7684\u6CB3\u95F4\u5730\u6D77\u5CB8\uFF0C\u5357\u63A5\u897F\u5883\u5317\u90E8\u3002\u6570\u767E\u5E74\u6765\u8FD9\u91CC\u4E00\u76F4\u662F\u94C1\u6C11\u52AB\u63A0\u7684\u730E\u573A\u3002"),houses:[],refs:["agot","maps"],confidence:"high"},{id:"great-wyk",kind:"island",region:"iron-islands",at:[162,768],rank:3,names:e("Great Wyk","\u5927\u5A01\u514B\u5C9B"),alt:["Great Wyk island"],summary:e("The largest of the Iron Islands, with more villages, mines and castles than any other. Most of it is held by the many branches of House Goodbrother.","\u94C1\u7FA4\u5C9B\u4E2D\u6700\u5927\u7684\u4E00\u5EA7\uFF0C\u6751\u5E84\u3001\u77FF\u5751\u4E0E\u57CE\u5821\u90FD\u6BD4\u5176\u4ED6\u5C9B\u5C7F\u591A\u3002\u5C9B\u4E0A\u5927\u90E8\u5206\u571F\u5730\u7531\u53E4\u67CF\u52D2\u5BB6\u65CF\u7684\u4F17\u591A\u5206\u652F\u5360\u636E\u3002"),houses:["goodbrother","sparr","merlyn","farwynd"],refs:["affc","twoiaf","maps"],confidence:"high"},{id:"old-wyk",kind:"island",region:"iron-islands",at:[200,762],rank:2,names:e("Old Wyk","\u8001\u5A01\u514B\u5C9B"),summary:e("The holy island of the ironborn, bleak and stony, where the Drowned God is said to have first given his people their kings. The ruins of the Grey King's hall crown Nagga's Hill.","\u94C1\u6C11\u7684\u5723\u5C9B\uFF0C\u8352\u51C9\u591A\u77F3\uFF1B\u4F20\u8BF4\u6DF9\u795E\u6700\u521D\u4FBF\u662F\u5728\u6B64\u4E3A\u5176\u5B50\u6C11\u6388\u4E88\u56FD\u738B\u3002\u7070\u738B\u5927\u5385\u7684\u9057\u8FF9\u76D8\u8E1E\u5728\u7EB3\u8FE6\u4E18\u9876\u4E0A\u3002"),houses:["drumm","stonehouse"],refs:["affc","twoiaf","maps"],confidence:"high"},{id:"harlaw",kind:"island",region:"iron-islands",at:[232,790],rank:3,names:e("Harlaw","\u54C8\u5C14\u6D1B\u5C9B"),summary:e("The most populous and richest of the Iron Islands, with gentler land than its neighbours. House Harlaw rules it from Ten Towers, with lesser Harlaws in several smaller castles.","\u94C1\u7FA4\u5C9B\u4E2D\u4EBA\u53E3\u6700\u591A\u3001\u6700\u5BCC\u5EB6\u7684\u5C9B\u5C7F\uFF0C\u571F\u5730\u4E5F\u6BD4\u90BB\u5C9B\u6E29\u548C\u3002\u54C8\u5C14\u6D1B\u5BB6\u65CF\u4EE5\u5341\u5854\u57CE\u4E3A\u4E3B\u5821\u7EDF\u6CBB\u6B64\u5C9B\uFF0C\u53E6\u6709\u6570\u4F4D\u54C8\u5C14\u6D1B\u65C1\u652F\u5206\u636E\u51E0\u5EA7\u5C0F\u57CE\u5821\u3002"),houses:["harlaw","volmark","kenning-of-harlaw"],refs:["affc","twoiaf","maps"],confidence:"high"},{id:"orkmont",kind:"island",region:"iron-islands",at:[187,738],rank:2,names:e("Orkmont","\u5965\u514B\u8499\u5C9B"),summary:e("A rugged northern island of the archipelago. The Greyjoys ruled from here as kings in the ages before they moved to Pyke.","\u7FA4\u5C9B\u5317\u90E8\u4E00\u5EA7\u5D0E\u5C96\u7684\u5C9B\u5C7F\u3002\u5728\u8FC1\u5C45\u6D3E\u514B\u4E4B\u524D\u7684\u5E74\u4EE3\uFF0C\u845B\u96F7\u4E54\u4F0A\u8BF8\u738B\u66FE\u4EE5\u6B64\u4E3A\u738B\u5EA7\u6240\u5728\u3002"),houses:["orkwood","tawney"],refs:["affc","twoiaf","maps"],confidence:"high"},{id:"blacktyde",kind:"island",region:"iron-islands",at:[222,734],rank:2,names:e("Blacktyde","\u9ED1\u6F6E\u5C9B"),summary:e("A small island in the north-east of the archipelago, nearest the mainland coast, ruled by House Blacktyde.","\u4F4D\u4E8E\u7FA4\u5C9B\u4E1C\u5317\u3001\u6700\u9760\u8FD1\u5927\u9646\u6D77\u5CB8\u7684\u5C0F\u5C9B\uFF0C\u7531\u5E03\u83B1\u5854\u5BB6\u65CF\u7EDF\u6CBB\u3002"),houses:["blacktyde"],refs:["affc","maps"],confidence:"high"},{id:"saltcliffe",kind:"island",region:"iron-islands",at:[156,808],rank:2,names:e("Saltcliffe","\u76D0\u5D16\u5C9B"),summary:e("A southern island of the archipelago, west of Pyke, home to Houses Saltcliffe and Sunderly.","\u7FA4\u5C9B\u5357\u90E8\u3001\u6D3E\u514B\u5C9B\u4EE5\u897F\u7684\u5C9B\u5C7F\uFF0C\u76D0\u5D16\u5BB6\u65CF\u4E0E\u6851\u5FB7\u5229\u5BB6\u65CF\u5C45\u4E8E\u6B64\u3002"),houses:["saltcliffe","sunderly"],refs:["affc","maps"],confidence:"high"},{id:"corpse-lake",kind:"lake",region:"iron-islands",at:[156,775],rank:1,names:e("Corpse Lake","\u5C38\u6E56"),summary:e("A lake on Great Wyk that gives its grim name to a branch of House Goodbrother, the Goodbrothers of Corpse Lake.","\u5927\u5A01\u514B\u5C9B\u4E0A\u7684\u4E00\u7247\u6E56\u6CCA\uFF0C\u53E4\u67CF\u52D2\u5BB6\u65CF\u7684\u4E00\u652F\u4EE5\u5B83\u4E3A\u540D\uFF0C\u79F0\u201C\u5C38\u6E56\u7684\u53E4\u67CF\u52D2\u201D\u3002"),houses:["goodbrother"],refs:["affc"],confidence:"low"},{id:"lordsport",kind:"town",region:"iron-islands",at:[199,810],rank:3,names:e("Lordsport","\u9886\u4E3B\u6E2F"),summary:e("The busiest harbour of the islands, a fishing and trading town a short ride from castle Pyke. Theon Greyjoy lands here on his return home, and the Botleys hold it for the Greyjoys.","\u7FA4\u5C9B\u6700\u7E41\u5FD9\u7684\u6E2F\u53E3\uFF0C\u79BB\u6D3E\u514B\u57CE\u4EC5\u4E00\u5C0F\u6BB5\u9A91\u7A0B\uFF0C\u662F\u6E14\u4E1A\u4E0E\u8D38\u6613\u5C0F\u9547\u3002\u5E2D\u6069\xB7\u845B\u96F7\u4E54\u4F0A\u5F52\u4E61\u65F6\u5728\u6B64\u767B\u5CB8\uFF0C\u6CE2\u7279\u5229\u5BB6\u65CF\u4E3A\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u9547\u5B88\u6B64\u5730\u3002"),houses:["botley"],refs:["acok","affc"],confidence:"medium"},{id:"iron-holt",kind:"castle",region:"iron-islands",at:[184,803],rank:1,names:e("Iron Holt","\u94C1\u6797\u57CE"),summary:e("Seat of House Wynch on the island of Pyke.","\u6E29\u5947\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u6D3E\u514B\u5C9B\u3002"),houses:["wynch"],refs:["affc"],confidence:"low"},{id:"ten-towers",kind:"castle",region:"iron-islands",at:[236,795],rank:3,names:e("Ten Towers","\u5341\u5854\u57CE"),summary:e("Seat of House Harlaw: a sprawling castle of ten towers raised by successive lords, each in his own style. Lord Rodrik keeps his great hoard of books here.","\u54C8\u5C14\u6D1B\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5386\u4EE3\u57CE\u4E3B\u5404\u6309\u5DF1\u610F\u589E\u5EFA\u9AD8\u5854\uFF0C\u7EC8\u6210\u4E00\u5EA7\u5341\u5854\u6797\u7ACB\u7684\u5E9E\u5927\u57CE\u5821\u3002\u7F57\u5FB7\u5229\u514B\u5927\u4EBA\u5C06\u4ED6\u7684\u5927\u91CF\u85CF\u4E66\u5B58\u653E\u4E8E\u6B64\u3002"),houses:["harlaw"],refs:["affc","twoiaf"],confidence:"medium"},{id:"harlaw-hall",kind:"castle",region:"iron-islands",at:[225,785],rank:1,names:e("Harlaw Hall","\u54C8\u5C14\u6D1B\u5385"),summary:e("A lesser Harlaw castle on Harlaw, home of old Sigfryd Silverhair.","\u54C8\u5C14\u6D1B\u5C9B\u4E0A\u4E00\u5EA7\u8F83\u5C0F\u7684\u54C8\u5C14\u6D1B\u5BB6\u65CF\u57CE\u5821\uFF0C\u5E74\u8FC8\u7684\u201C\u94F6\u53D1\u201D\u5E2D\u683C\u5F17\u91CC\u5FB7\u5C45\u4E8E\u6B64\u3002"),houses:["harlaw"],refs:["affc"],confidence:"low"},{id:"grey-garden",kind:"castle",region:"iron-islands",at:[242,788],rank:1,names:e("Grey Garden","\u7070\u56ED"),summary:e("A Harlaw holding on Harlaw, seat of Ser Harras Harlaw, the Knight.","\u54C8\u5C14\u6D1B\u5C9B\u4E0A\u7684\u54C8\u5C14\u6D1B\u5BB6\u65CF\u9886\u5730\uFF0C\u201C\u9A91\u58EB\u201D\u54C8\u62C9\u65AF\xB7\u54C8\u5C14\u6D1B\u7235\u58EB\u7684\u5C45\u6240\u3002"),houses:["harlaw"],refs:["affc"],confidence:"low"},{id:"tower-of-glimmering",kind:"castle",region:"iron-islands",at:[229,798],rank:1,names:e("Tower of Glimmering","\u5FAE\u5149\u5854"),summary:e("A Harlaw tower on Harlaw, held by Hotho Humpback.","\u54C8\u5C14\u6D1B\u5C9B\u4E0A\u7684\u4E00\u5EA7\u54C8\u5C14\u6D1B\u5BB6\u65CF\u5854\u5821\uFF0C\u7531\u201C\u9A7C\u80CC\u201D\u970D\u7D22\u636E\u5B88\u3002"),houses:["harlaw"],refs:["affc"],confidence:"low"},{id:"harridan-hill",kind:"castle",region:"iron-islands",at:[234,783],rank:1,names:e("Harridan Hill","\u608D\u5987\u4E18"),summary:e("A Harlaw holding on Harlaw, seat of Boremund the Blue.","\u54C8\u5C14\u6D1B\u5C9B\u4E0A\u7684\u54C8\u5C14\u6D1B\u5BB6\u65CF\u9886\u5730\uFF0C\u201C\u84DD\u8863\u201D\u6CE2\u5C14\u8499\u5FB7\u7684\u5C45\u6240\u3002"),houses:["harlaw"],refs:["affc"],confidence:"low"},{id:"naggas-hill",kind:"sacred",region:"iron-islands",at:[203,758],rank:3,names:e("Nagga's Hill","\u7EB3\u8FE6\u4E18"),alt:["Grey King's Hall","Nagga's Ribs","Kingsmoot","\u7070\u738B\u5927\u5385","\u7EB3\u8FE6\u808B\u9AA8","\u9009\u738B\u4F1A"],summary:e("The holiest ground of the ironborn, on Old Wyk. Great stone-like ribs, said to be the bones of the sea dragon Nagga slain by the Grey King, stand around the ruins of his hall, and it is here that captains gather when a kingsmoot is called to choose a king.","\u94C1\u6C11\u6700\u795E\u5723\u7684\u5730\u65B9\uFF0C\u4F4D\u4E8E\u8001\u5A01\u514B\u5C9B\u3002\u4F20\u8BF4\u7070\u738B\u6740\u6B7B\u4E86\u6D77\u9F99\u7EB3\u8FE6\uFF0C\u5176\u5DE8\u5927\u5982\u77F3\u7684\u808B\u9AA8\u4ECD\u73AF\u7ACB\u5728\u7070\u738B\u5927\u5385\u7684\u5E9F\u589F\u5468\u56F4\u3002\u6BCF\u9022\u53EC\u5F00\u9009\u738B\u4F1A\uFF0C\u5404\u8239\u957F\u4FBF\u805A\u96C6\u4E8E\u6B64\u63A8\u4E3E\u56FD\u738B\u3002"),spoiler:e("Aeron Damphair calls a kingsmoot here after Balon's death; Euron wins it.","\u5DF4\u9686\u6B7B\u540E\uFF0C\u201C\u6E7F\u53D1\u201D\u4F0A\u4F26\u5728\u6B64\u53EC\u5F00\u9009\u738B\u4F1A\uFF0C\u6538\u4F26\u80DC\u51FA\u3002"),houses:[],refs:["affc","twoiaf"],confidence:"high"},{id:"hammerhorn",kind:"castle",region:"iron-islands",at:[172,766],rank:2,names:e("Hammerhorn","\u9524\u89D2\u57CE"),summary:e("Seat of the senior branch of House Goodbrother on Great Wyk, held by Lord Gorold Goodbrother.","\u5927\u5A01\u514B\u5C9B\u4E0A\u53E4\u67CF\u52D2\u5BB6\u65CF\u957F\u623F\u7684\u5C45\u57CE\uFF0C\u7531\u6208\u7F57\u5FB7\xB7\u53E4\u67CF\u52D2\u5927\u4EBA\u638C\u7BA1\u3002"),houses:["goodbrother"],refs:["affc"],confidence:"medium"},{id:"pebbleton",kind:"town",region:"iron-islands",at:[179,777],rank:1,names:e("Pebbleton","\u5375\u77F3\u9547"),summary:e("A village and holdfast on the shore of Great Wyk, seat of House Merlyn. Aeron Damphair is preaching nearby when word reaches him of Balon's death.","\u5927\u5A01\u514B\u5C9B\u6D77\u8FB9\u7684\u6751\u843D\u4E0E\u5C0F\u5821\uFF0C\u6885\u6797\u5BB6\u65CF\u7684\u5C45\u6240\u3002\u201C\u6E7F\u53D1\u201D\u4F0A\u4F26\u5728\u9644\u8FD1\u5E03\u9053\u65F6\u5F97\u77E5\u4E86\u5DF4\u9686\u7684\u6B7B\u8BAF\u3002"),houses:["merlyn"],refs:["affc"],confidence:"medium"},{id:"shatterstone",kind:"castle",region:"iron-islands",at:[146,780],rank:1,names:e("Shatterstone","\u788E\u77F3\u5821"),summary:e("A Goodbrother holding on Great Wyk.","\u5927\u5A01\u514B\u5C9B\u4E0A\u7684\u53E4\u67CF\u52D2\u5BB6\u65CF\u9886\u5730\u3002"),houses:["goodbrother"],refs:["affc"],confidence:"low"},{id:"downdelving",kind:"castle",region:"iron-islands",at:[154,758],rank:1,names:e("Downdelving","\u6DF1\u6398\u57CE"),summary:e("A Goodbrother holding on Great Wyk, whose name recalls the island's mines.","\u5927\u5A01\u514B\u5C9B\u4E0A\u7684\u53E4\u67CF\u52D2\u5BB6\u65CF\u9886\u5730\uFF0C\u5176\u540D\u4EE4\u4EBA\u60F3\u8D77\u5C9B\u4E0A\u7684\u77FF\u5751\u3002"),houses:["goodbrother"],refs:["affc"],confidence:"low"},{id:"crow-spike-keep",kind:"castle",region:"iron-islands",at:[170,782],rank:1,names:e("Crow Spike Keep","\u9E26\u9489\u5821"),summary:e("A Goodbrother holding on Great Wyk.","\u5927\u5A01\u514B\u5C9B\u4E0A\u7684\u53E4\u67CF\u52D2\u5BB6\u65CF\u9886\u5730\u3002"),houses:["goodbrother"],refs:["affc"],confidence:"low"},{id:"sealskin-point",kind:"landmark",region:"iron-islands",at:[144,763],rank:1,names:e("Sealskin Point","\u6D77\u8C79\u76AE\u89D2"),summary:e("A point on Great Wyk held by a branch of House Farwynd.","\u5927\u5A01\u514B\u5C9B\u4E0A\u7684\u4E00\u5904\u5CAC\u89D2\uFF0C\u7531\u6CD5\u6E29\u5FB7\u5BB6\u65CF\u7684\u4E00\u652F\u636E\u6709\u3002"),houses:["farwynd"],refs:["affc"],confidence:"low"},{id:"castle-blacktyde",kind:"castle",region:"iron-islands",at:[225,738],rank:1,names:e("Blacktyde (castle)","\u9ED1\u6F6E\u5821"),summary:e("The castle of House Blacktyde on the island of the same name.","\u5E03\u83B1\u5854\u5BB6\u65CF\u4F4D\u4E8E\u540C\u540D\u5C9B\u5C7F\u4E0A\u7684\u57CE\u5821\u3002"),houses:["blacktyde"],refs:["affc"],confidence:"low"},{id:"castle-saltcliffe",kind:"castle",region:"iron-islands",at:[159,811],rank:1,names:e("Saltcliffe (castle)","\u76D0\u5D16\u5821"),summary:e("The castle of House Saltcliffe on the island of the same name.","\u76D0\u5D16\u5BB6\u65CF\u4F4D\u4E8E\u540C\u540D\u5C9B\u5C7F\u4E0A\u7684\u57CE\u5821\u3002"),houses:["saltcliffe"],refs:["affc"],confidence:"low"},{id:"lonely-light",kind:"castle",region:"iron-islands",at:[104,768],rank:2,names:e("Lonely Light","\u5B64\u706F\u5C9B"),summary:e("The westernmost of the ironborn holdings, a rock in the Sunset Sea some days' sail beyond Great Wyk, peopled by seals and seabirds and ruled by House Farwynd. Its true distance is far greater than this map can show.","\u94C1\u6C11\u6700\u897F\u7AEF\u7684\u9886\u5730\uFF1A\u65E5\u843D\u4E4B\u6D77\u4E2D\u7684\u4E00\u5757\u5B64\u5CA9\uFF0C\u8DDD\u5927\u5A01\u514B\u5C9B\u9700\u822A\u884C\u6570\u65E5\uFF0C\u5C9B\u4E0A\u591A\u6D77\u8C79\u4E0E\u6D77\u9E1F\uFF0C\u7531\u6CD5\u6E29\u5FB7\u5BB6\u65CF\u7EDF\u6CBB\u3002\u5176\u5B9E\u9645\u8DDD\u79BB\u8FDC\u6BD4\u672C\u56FE\u6240\u793A\u66F4\u8FDC\u3002"),houses:["farwynd"],refs:["affc","twoiaf"],confidence:"low"},{id:"fair-isle",kind:"island",region:"westerlands",at:[214,842],rank:2,names:e("Fair Isle","\u4ED9\u5973\u5C9B"),summary:e("An island off the westerlands coast, north-west of Lannisport, that shelters the approaches to the city. House Farman rules it from Faircastle.","\u897F\u5883\u6D77\u5CB8\u5916\u3001\u5170\u5C3C\u65AF\u6E2F\u897F\u5317\u65B9\u7684\u5C9B\u5C7F\uFF0C\u5C4F\u62A4\u7740\u901A\u5F80\u8BE5\u57CE\u7684\u6D77\u8DEF\u3002\u6CD5\u66FC\u5BB6\u65CF\u5728\u4ED9\u5973\u57CE\u7EDF\u6CBB\u6B64\u5C9B\u3002"),houses:["farman"],refs:["affc","maps","twoiaf"],confidence:"high"},{id:"westerlands-hills",kind:"mountain",region:"westerlands",at:[290,884],rank:2,names:e("Hills of the Westerlands","\u897F\u5883\u4E18\u9675"),alt:["Western hills"],summary:e("The rugged, mine-riddled hills that fill the westerlands and divide them from the riverlands. Their gold and silver are the source of Lannister wealth; the passes through them are guarded by castles such as the Golden Tooth.","\u5E03\u6EE1\u77FF\u4E95\u7684\u5D0E\u5C96\u4E18\u9675\uFF0C\u8986\u76D6\u897F\u5883\u5927\u90E8\uFF0C\u5E76\u5C06\u5176\u4E0E\u6CB3\u95F4\u5730\u5206\u9694\u3002\u5170\u5C3C\u65AF\u7279\u7684\u8D22\u5BCC\u5373\u51FA\u81EA\u5176\u4E2D\u7684\u91D1\u94F6\uFF1B\u7A7F\u8D8A\u4E18\u9675\u7684\u9698\u53E3\u7531\u91D1\u7259\u57CE\u7B49\u57CE\u5821\u627C\u5B88\u3002"),houses:[],refs:["agot","twoiaf"],confidence:"medium"},{id:"golden-tooth",kind:"castle",region:"westerlands",at:[282,848],rank:3,names:e("Golden Tooth","\u91D1\u7259\u57CE"),alt:["The Golden Tooth","Golden Tooth pass"],summary:e("A castle on a mountain spur that commands the pass where the road from Riverrun climbs into the westerlands. Held by House Lefford, it is the door between the two regions. Jaime Lannister broke the riverlords' forces beneath its walls at the start of the war.","\u5EFA\u4E8E\u5C71\u810A\u4E0A\u7684\u57CE\u5821\uFF0C\u627C\u5B88\u7531\u5954\u6D41\u57CE\u8FDB\u5165\u897F\u5883\u7684\u5C71\u9053\u9698\u53E3\u3002\u5B83\u7531\u96F7\u4F5B\u5FB7\u5BB6\u65CF\u636E\u5B88\uFF0C\u662F\u4E24\u5730\u4E4B\u95F4\u7684\u95E8\u6237\u3002\u6218\u4E89\u4F0A\u59CB\uFF0C\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279\u5728\u5176\u57CE\u4E0B\u51FB\u6E83\u4E86\u6CB3\u95F4\u8BF8\u4FAF\u7684\u519B\u961F\u3002"),houses:["lefford"],refs:["agot","maps","twoiaf"],confidence:"high"},{id:"banefort",kind:"castle",region:"westerlands",at:[276,808],rank:2,names:e("Banefort","\u6591\u6797\u5821"),alt:["The Banefort"],summary:e("A castle on the northern coast of the westerlands, facing Ironman's Bay and keeping watch against ironborn raids. It is the seat of House Banefort.","\u897F\u5883\u5317\u90E8\u6D77\u5CB8\u7684\u57CE\u5821\uFF0C\u9762\u671D\u94C1\u6C11\u6E7E\uFF0C\u8B66\u6212\u94C1\u6C11\u7684\u52AB\u63A0\uFF0C\u662F\u6591\u6797\u5BB6\u65CF\u7684\u5C45\u57CE\u3002"),houses:["banefort"],refs:["acok","maps","twoiaf"],confidence:"medium"},{id:"the-crag",kind:"castle",region:"westerlands",at:[259,820],rank:2,names:e("The Crag","\u5CED\u5CA9\u57CE"),alt:["Crag"],summary:e("The ancient, crumbling seaside castle of House Westerling, whose gold mines have long been worked out.","\u7EF4\u65AF\u7279\u6797\u5BB6\u65CF\u53E4\u8001\u800C\u7834\u8D25\u7684\u4E34\u6D77\u57CE\u5821\uFF0C\u5176\u91D1\u77FF\u65E9\u5DF2\u91C7\u5C3D\u3002"),spoiler:e("Robb Stark storms the Crag, is wounded, and is nursed by Jeyne Westerling, whom he marries.","\u7F57\u67CF\xB7\u53F2\u5854\u514B\u653B\u4E0B\u5CED\u5CA9\u57CE\u65F6\u8D1F\u4F24\uFF0C\u7531\u6770\u59AE\xB7\u7EF4\u65AF\u7279\u6797\u7167\u6599\uFF0C\u5E76\u5A36\u5979\u4E3A\u59BB\u3002"),houses:["westerling"],refs:["acok","asos","maps"],confidence:"medium"},{id:"crakehall",kind:"castle",region:"westerlands",at:[254,834],rank:2,names:e("Crakehall","\u514B\u96F7\u514B\u8D6B\u57CE"),summary:e("Seat of House Crakehall on the coast north of Casterly Rock, a strong castle whose lords are among the foremost Lannister bannermen.","\u514B\u96F7\u514B\u8D6B\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u51EF\u5CA9\u57CE\u4EE5\u5317\u7684\u6D77\u5CB8\uFF0C\u57CE\u5821\u575A\u56FA\uFF0C\u5176\u9886\u4E3B\u662F\u5170\u5C3C\u65AF\u7279\u6700\u91CD\u8981\u7684\u5C01\u81E3\u4E4B\u4E00\u3002"),houses:["crakehall"],refs:["agot","maps","twoiaf"],confidence:"medium"},{id:"castamere",kind:"ruin",region:"westerlands",at:[271,824],rank:2,names:e("Castamere","\u5361\u65AF\u7279\u6885"),alt:["Rains of Castamere","\u5361\u65AF\u7279\u6885\u7684\u96E8\u5B63"],summary:e('The ruined seat of House Reyne, whose halls ran deep into a gold mine. When the Reynes rebelled, Tywin Lannister dammed a stream and flooded the mine with the family inside; the hall has stood empty ever since, and its fate lives on in "The Rains of Castamere".',"\u96F7\u8036\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\u9057\u5740\uFF0C\u5176\u5385\u5802\u6DF1\u5165\u91D1\u77FF\u4E4B\u4E2D\u3002\u96F7\u8036\u65AF\u5BB6\u65CF\u53DB\u4E71\u65F6\uFF0C\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u7B51\u575D\u5F15\u6C34\uFF0C\u5C06\u8EB2\u5728\u77FF\u4E2D\u7684\u6574\u4E2A\u5BB6\u65CF\u6DF9\u6CA1\uFF1B\u6B64\u540E\u57CE\u5821\u4E00\u76F4\u8352\u5E9F\uFF0C\u90A3\u6BB5\u5F80\u4E8B\u6D41\u4F20\u5728\u6B4C\u8C23\u300A\u5361\u65AF\u7279\u6885\u7684\u96E8\u5B63\u300B\u4E2D\u3002"),spoiler:e("After the Red Wedding the Lannisters grant Castamere to Rolph Spicer.","\u8840\u8272\u5A5A\u793C\u4E4B\u540E\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u5C06\u5361\u65AF\u7279\u6885\u8D50\u7ED9\u7F57\u592B\xB7\u65AF\u6D3E\u745F\u3002"),houses:["reyne"],refs:["asos","twoiaf","maps"],confidence:"medium"},{id:"tarbeck-hall",kind:"ruin",region:"westerlands",at:[284,830],rank:1,names:e("Tarbeck Hall","\u5854\u8D1D\u514B\u5385"),summary:e("The ruins of the Tarbeck seat, pulled down by Tywin Lannister when the Tarbecks joined the Reynes in revolt.","\u5854\u8D1D\u514B\u5BB6\u65CF\u5C45\u57CE\u7684\u5E9F\u589F\uFF1B\u5854\u8D1D\u514B\u5BB6\u968F\u96F7\u8036\u65AF\u5BB6\u65CF\u53DB\u4E71\u540E\uFF0C\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u5C06\u5176\u5937\u4E3A\u5E73\u5730\u3002"),houses:["tarbeck"],refs:["asos","twoiaf"],confidence:"low"},{id:"sarsfield",kind:"castle",region:"westerlands",at:[268,843],rank:1,names:e("Sarsfield","\u8428\u65AF\u83F2\u5C14\u57CE"),summary:e("Seat of House Sarsfield in the hills north-east of Casterly Rock.","\u8428\u65AF\u83F2\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u51EF\u5CA9\u57CE\u4E1C\u5317\u65B9\u7684\u4E18\u9675\u4E2D\u3002"),houses:["sarsfield"],refs:["maps","twoiaf"],confidence:"low"},{id:"oxcross",kind:"battle",region:"westerlands",at:[260,850],rank:2,names:e("Oxcross","\u725B\u6E21"),alt:["Battle of Oxcross","\u725B\u6E21\u4E4B\u6218"],summary:e("A small town in the westerlands hills on the way from the Golden Tooth toward Casterly Rock, where a Lannister host was raised and camped early in the War of the Five Kings.","\u897F\u5883\u4E18\u9675\u4E2D\u7684\u5C0F\u9547\uFF0C\u4F4D\u4E8E\u91D1\u7259\u57CE\u901A\u5F80\u51EF\u5CA9\u57CE\u7684\u8DEF\u4E0A\uFF1B\u4E94\u738B\u4E4B\u6218\u521D\u671F\uFF0C\u4E00\u652F\u65B0\u52DF\u7684\u5170\u5C3C\u65AF\u7279\u5927\u519B\u66FE\u5728\u6B64\u624E\u8425\u3002"),spoiler:e("Robb Stark slips through the Golden Tooth and falls on the camp by night; Stafford Lannister is killed and the new host is scattered.","\u7F57\u67CF\xB7\u53F2\u5854\u514B\u7A7F\u8FC7\u91D1\u7259\u57CE\u4E00\u5E26\u7684\u5C71\u8DEF\uFF0C\u591C\u88AD\u8425\u5730\uFF1B\u53F2\u5854\u4F5B\xB7\u5170\u5C3C\u65AF\u7279\u88AB\u6740\uFF0C\u65B0\u519B\u6E83\u6563\u3002"),houses:[],refs:["acok","asos"],confidence:"medium"},{id:"ashemark",kind:"castle",region:"westerlands",at:[271,866],rank:2,names:e("Ashemark","\u7070\u6807\u57CE"),summary:e("Seat of House Marbrand, in the hills east of Lannisport.","\u9A6C\u5C14\u5E03\u5170\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u5170\u5C3C\u65AF\u6E2F\u4EE5\u4E1C\u7684\u4E18\u9675\u4E2D\u3002"),spoiler:e("Taken by Robb Stark during his westerlands campaign.","\u7F57\u67CF\xB7\u53F2\u5854\u514B\u5728\u897F\u5883\u4F5C\u6218\u671F\u95F4\u653B\u4E0B\u6B64\u57CE\u3002"),houses:["marbrand"],refs:["acok","maps","twoiaf"],confidence:"medium"},{id:"hornvale",kind:"castle",region:"westerlands",at:[287,893],rank:1,names:e("Hornvale","\u89D2\u8C37"),summary:e("Seat of House Brax, in a vale of the eastern westerlands hills near the riverlands border.","\u5E03\u62C9\u514B\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u897F\u5883\u4E1C\u90E8\u4E18\u9675\u4E2D\u4E00\u5904\u8C37\u5730\uFF0C\u9760\u8FD1\u6CB3\u95F4\u5730\u8FB9\u754C\u3002"),houses:["brax"],refs:["agot","maps","twoiaf"],confidence:"low"},{id:"silverhill",kind:"castle",region:"westerlands",at:[268,902],rank:1,names:e("Silverhill","\u94F6\u5C71\u57CE"),summary:e("Seat of House Serrett, in the hills south-east of Lannisport; its name hints at the silver of the western hills.","\u8D5B\u745E\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u5170\u5C3C\u65AF\u6E2F\u4E1C\u5357\u65B9\u7684\u4E18\u9675\u4E2D\uFF0C\u5176\u540D\u6697\u793A\u4E86\u897F\u90E8\u7FA4\u5C71\u4E2D\u7684\u94F6\u77FF\u3002"),houses:["serrett"],refs:["maps","twoiaf"],confidence:"low"},{id:"deep-den",kind:"castle",region:"westerlands",at:[300,906],rank:2,names:e("Deep Den","\u6DF1\u7A74\u57CE"),summary:e("Seat of House Lydden on the eastern edge of the westerlands, watching the goldroad where it leaves the hills for the Reach and the crownlands.","\u83B1\u767B\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u897F\u5883\u4E1C\u7F18\uFF0C\u5B88\u671B\u7740\u9EC4\u91D1\u5927\u9053\u51FA\u5C71\u901A\u5F80\u6CB3\u6E7E\u5730\u4E0E\u738B\u9886\u7684\u8DEF\u6BB5\u3002"),houses:["lydden"],refs:["agot","maps","twoiaf"],confidence:"medium"},{id:"kayce",kind:"town",region:"westerlands",at:[236,904],rank:2,names:e("Kayce","\u51EF\u65AF"),summary:e("A coastal town and castle south of Lannisport, held by House Kenning for the Lannisters.","\u5170\u5C3C\u65AF\u6E2F\u4EE5\u5357\u7684\u6D77\u6EE8\u57CE\u9547\u4E0E\u57CE\u5821\uFF0C\u7531\u80AF\u5B81\u5BB6\u65CF\u4E3A\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u9547\u5B88\u3002"),houses:["kenning-of-kayce"],refs:["acok","maps","twoiaf"],confidence:"medium"},{id:"feastfires",kind:"castle",region:"westerlands",at:[226,938],rank:2,names:e("Feastfires","\u5BB4\u706B\u57CE"),summary:e("Seat of House Prester on the southern westerlands coast, toward the border with the Reach.","\u666E\u745E\u65AF\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u897F\u5883\u5357\u90E8\u6D77\u5CB8\uFF0C\u9760\u8FD1\u4E0E\u6CB3\u6E7E\u5730\u7684\u8FB9\u754C\u3002"),houses:["prester"],refs:["maps","twoiaf"],confidence:"medium"},{id:"faircastle",kind:"castle",region:"westerlands",at:[218,846],rank:2,names:e("Faircastle","\u4ED9\u5973\u57CE"),summary:e("Seat of House Farman on Fair Isle, guarding the sea road to Lannisport.","\u6CD5\u66FC\u5BB6\u65CF\u5728\u4ED9\u5973\u5C9B\u4E0A\u7684\u5C45\u57CE\uFF0C\u5B88\u536B\u7740\u901A\u5F80\u5170\u5C3C\u65AF\u6E2F\u7684\u6D77\u8DEF\u3002"),spoiler:e("Euron Greyjoy's ironborn raid Fair Isle and the westerlands coast after the kingsmoot.","\u9009\u738B\u4F1A\u4E4B\u540E\uFF0C\u6538\u4F26\xB7\u845B\u96F7\u4E54\u4F0A\u7684\u94C1\u6C11\u88AD\u63A0\u4E86\u4ED9\u5973\u5C9B\u4E0E\u897F\u5883\u6D77\u5CB8\u3002"),houses:["farman"],refs:["affc","maps","twoiaf"],confidence:"medium"},{id:"cornfield",kind:"castle",region:"westerlands",at:[262,924],rank:1,names:e("Cornfield","\u7389\u7C73\u7530"),summary:e("Seat of House Swyft in the southern westerlands; the books give no exact position, so this marker is approximate.","\u53F2\u5A01\u4F5B\u5BB6\u65CF\u7684\u5C45\u6240\uFF0C\u4F4D\u4E8E\u897F\u5883\u5357\u90E8\uFF1B\u4E66\u4E2D\u672A\u7ED9\u51FA\u786E\u5207\u4F4D\u7F6E\uFF0C\u6B64\u6807\u8BB0\u4EC5\u4E3A\u4F30\u8BA1\u3002"),houses:["swyft"],refs:["acok","twoiaf"],confidence:"low"},{id:"cleganes-keep",kind:"castle",region:"westerlands",at:[258,888],rank:1,names:e("Clegane's Keep","\u514B\u91CC\u5188\u5821"),summary:e("The modest keep and lands granted to the Cleganes by Lord Tytos Lannister. Sandor remembers it as the home where Gregor burned his face; its position here is only a guess.","\u6CF0\u9640\u65AF\xB7\u5170\u5C3C\u65AF\u7279\u516C\u7235\u8D4F\u7ED9\u514B\u91CC\u5188\u5BB6\u7684\u5C0F\u57CE\u5821\u4E0E\u9886\u5730\u3002\u5728\u6851\u94CE\u7684\u8BB0\u5FC6\u91CC\uFF0C\u683C\u96F7\u679C\u6B63\u662F\u5728\u8FD9\u91CC\u70E7\u4F24\u4E86\u4ED6\u7684\u8138\uFF1B\u6B64\u5904\u4F4D\u7F6E\u4EC5\u4E3A\u63A8\u6D4B\u3002"),houses:["clegane"],refs:["agot","twoiaf"],confidence:"low"}]};export{n as default};
